const upsertAgentThread = `-- name: UpsertAgentThread :exec
INSERT INTO agent_threads (
    thread_id,
    name,
    prompt,
    model,
    cwd,
    status,
    port,
    pid,
    created_at,
    updated_at,
    owner_thread_id,
    parent_agent_id,
    agent_type,
    agent_memory_scope,
    config_override,
    agent_key,
    prompt_version_id,
    pending_launch,
    manually_renamed
)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, COALESCE(?15, '{}'), ?16, ?17, ?18, ?19)
ON CONFLICT (thread_id) DO UPDATE
SET name = excluded.name,
    prompt = excluded.prompt,
    model = excluded.model,
    cwd = excluded.cwd,
    status = excluded.status,
    port = excluded.port,
    pid = excluded.pid,
    updated_at = excluded.updated_at,
    owner_thread_id = excluded.owner_thread_id,
    parent_agent_id = excluded.parent_agent_id,
    agent_type = excluded.agent_type,
    agent_memory_scope = excluded.agent_memory_scope,
    config_override = excluded.config_override,
    agent_key = excluded.agent_key,
    prompt_version_id = excluded.prompt_version_id,
    pending_launch = excluded.pending_launch,
    manually_renamed = excluded.manually_renamed
`

